insert into questions (id, type, data, status) values ('q_mtf_nerve_fibre_types_001', 'MTF', '{"dateAdded":"2026-10-12","rotationIndex":142,"stem":"Regarding peripheral nerve fibre types:","choices":["Aδ fibres are thinly myelinated","C fibres are unmyelinated and conduct at approximately 0.5–2 m/s","Aβ fibres are the principal afferents mediating nociception","Preganglionic autonomic fibres are B fibres","During a peripheral nerve block, Aα motor fibres are blocked before C fibres"],"correct":[true,true,false,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Fibre classification rests on diameter, myelination and conduction velocity, which are closely related: larger, more heavily myelinated fibres conduct faster. Nociceptive afferents are the thin A&delta; and C fibres; the fibre type also determines the order in which a local anaesthetic block develops.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; A&delta; fibres are thinly myelinated, small-diameter fibres (about 1&ndash;5 &micro;m) with conduction velocities of about 5&ndash;30 m/s.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; C fibres are the smallest and slowest fibres, with conduction velocities of about 0.5&ndash;2 m/s.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; A&beta; fibres are large, fast fibres carrying low-threshold touch, pressure and vibration. They are not nociceptive in health, although after nerve injury they can contribute to allodynia through central changes.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; B fibres are small, lightly myelinated preganglionic autonomic fibres (conduction velocity 3&ndash;15 m/s).</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; The largest fibres are the last to be blocked. Clinically, sympathetic (B) fibres are blocked first, then pain and temperature (C and A&delta;), then touch (A&beta;), with motor A&alpha; fibres blocked last. This is why a patient can lose pain sensation while still moving the limb.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Peripheral Nerve Fibre Types</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Peripheral nerve fibres are classified by diameter, myelination and conduction velocity. Fibre type determines function, and also predicts the sequence in which a local anaesthetic block develops and recedes.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Fibre Classification</div><table style=\"margin:0\"><tr><th>Fibre</th><th>Diameter</th><th>Myelination</th><th>Velocity (m/s)</th><th>Main function</th></tr><tr><td>A&alpha;</td><td>13&ndash;20 &micro;m</td><td>Heavy</td><td>70&ndash;120</td><td>Motor to skeletal muscle; proprioception (muscle spindle Ia, tendon organ Ib)</td></tr><tr><td>A&beta;</td><td>6&ndash;12 &micro;m</td><td>Heavy</td><td>30&ndash;70</td><td>Touch, pressure, vibration</td></tr><tr><td>A&gamma;</td><td>3&ndash;6 &micro;m</td><td>Moderate</td><td>15&ndash;30</td><td>Motor to muscle spindles (intrafusal fibres)</td></tr><tr><td>A&delta;</td><td>1&ndash;5 &micro;m</td><td>Thin</td><td>5&ndash;30</td><td>Fast first pain, cold, crude touch</td></tr><tr><td>B</td><td>&lt;3 &micro;m</td><td>Light</td><td>3&ndash;15</td><td>Preganglionic autonomic</td></tr><tr><td>C</td><td>0.2&ndash;1.5 &micro;m</td><td>None</td><td>0.5&ndash;2</td><td>Slow second pain, warmth, itch; postganglionic sympathetic efferents</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Afferents from muscle are sometimes classified by the Lloyd&ndash;Hunt scheme: group I (Ia, Ib) = A&alpha;, group II = A&beta;, group III = A&delta;, group IV = C.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Order of Block with Local Anaesthetic</div><table style=\"margin:0\"><tr><th>Order</th><th>Fibres blocked</th><th>Clinical sign</th></tr><tr><td>1</td><td>B (preganglionic sympathetic)</td><td>Vasodilatation, warm limb, hypotension in neuraxial block</td></tr><tr><td>2</td><td>C and A&delta;</td><td>Loss of temperature (cold) sensation, then pain</td></tr><tr><td>3</td><td>A&gamma;</td><td>Loss of muscle tone and spindle feedback</td></tr><tr><td>4</td><td>A&beta;</td><td>Loss of touch and pressure</td></tr><tr><td>5</td><td>A&alpha;</td><td>Loss of motor power and proprioception</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Recovery occurs in the reverse order. In vitro, myelinated fibres are blocked more readily than unmyelinated fibres of the same diameter, but in clinical practice smaller fibres are blocked first.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_gate_control_tens_001', 'SBA', '{"dateAdded":"2026-10-12","rotationIndex":143,"question":"A patient with chronic neuropathic limb pain finds relief from high-frequency (50–100 Hz), low-intensity transcutaneous electrical nerve stimulation (TENS) applied over the painful area. Which mechanism best explains this?","choices":["Selective conduction block of unmyelinated C fibres","Activation of large-diameter myelinated afferents, which inhibit nociceptive transmission in the dorsal horn","Depletion of substance P from nociceptor terminals","Activation of small-diameter afferents, triggering endogenous opioid release","Antagonism of NMDA receptors in the dorsal horn"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The gate control theory (Melzack and Wall, 1965) proposed that dorsal horn transmission of nociceptive input is regulated by competing input from large and small fibres, acting through inhibitory interneurones of the substantia gelatinosa. Conventional TENS is the clinical application of this idea.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> TENS at conventional settings produces a comfortable paraesthesia without pain and does not block conduction in C fibres; the nerve is not anaesthetised.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> Low-intensity, high-frequency stimulation preferentially recruits large A&beta; fibres (lowest electrical threshold). These excite substantia gelatinosa inhibitory interneurones, which inhibit the projection (T) neurone and &ldquo;close the gate&rdquo; to nociceptive input from A&delta; and C fibres.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Substance P depletion is the mechanism of topical capsaicin, not TENS.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Strong, low-frequency (2&ndash;4 Hz), high-intensity &ldquo;acupuncture-like&rdquo; TENS is thought to work by recruiting small fibres and opioid-mediated descending inhibition. This is not the mechanism of conventional high-frequency TENS.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> NMDA receptor antagonism is the mechanism of ketamine and similar agents, not TENS.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">TENS and Gate Control Theory</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Transcutaneous Electrical Nerve Stimulation (TENS) is a non-invasive, low-cost, patient-controlled method of pain relief. A small battery-powered pulse generator delivers electrical pulses to the skin through adhesive surface electrodes.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Parameters that can be modified on a TENS machine include pulse duration (in microseconds), pulse frequency (in Hz or pulses/sec) and pulse amplitude (in milliamperes).</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Gate Control Theory</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Melzack and Wall (1965) proposed that the substantia gelatinosa (lamina II) acts as a &ldquo;gate&rdquo; modulating transmission to the dorsal horn projection (T) neurone. The balance of large-fibre and small-fibre input, together with descending control from the brain, determines whether the gate is open or closed.</p><div style=\"text-align:center\"><img src=\"images/gate-control-theory.svg\" alt=\"Diagram of the gate control theory: A-beta afferents excite the substantia gelatinosa inhibitory interneuron and the projection T cell; A-delta and C afferents inhibit the interneuron and excite the T cell; descending brain pathways modulate the interneuron; the T cell projects via the spinothalamic tract\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Effect on the Gate</div><table style=\"margin:0\"><tr><th>Input</th><th>Effect on SG inhibitory interneurone</th><th>Effect on T cell</th><th>Net result</th></tr><tr><td>A&beta; (large fibres)</td><td>Excites</td><td>Excites, but also inhibited via interneurone</td><td>Gate closes; less pain transmitted</td></tr><tr><td>A&delta; and C (small fibres)</td><td>Inhibits</td><td>Excites</td><td>Gate opens; more pain transmitted</td></tr><tr><td>Descending brain pathways</td><td>Modulate (usually enhance inhibition)</td><td>Indirect</td><td>Gate closes (attention, expectation, descending inhibition)</td></tr></table><table style=\"margin:12px 0 0\"><tr><th>Application of the gate concept</th><th>Principle</th></tr><tr><td>Rubbing a bruise or shaking a hand after injury</td><td>Everyday recruitment of A&beta; fibres</td></tr><tr><td>Conventional TENS</td><td>Comfortable paraesthesia over the painful area; A&beta; recruitment closes the gate</td></tr><tr><td>Spinal cord stimulation</td><td>Developed from gate control theory; paraesthesia-based SCS stimulates dorsal column A&beta; fibres</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Modern interpretations place greater emphasis on GABA/glycine-mediated inhibition. Loss of this inhibition (disinhibition) after nerve injury can allow A&beta; input to drive nociceptive circuits, producing mechanical allodynia.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Types of TENS</div><table style=\"margin:0\"><tr><th>Type</th><th>Frequency</th><th>Intensity</th><th>Fibres activated</th><th>Proposed mechanism</th></tr><tr><td><strong>Conventional TENS</strong></td><td>High (~50&ndash;100 Hz)</td><td>Low &mdash; comfortable tingling, no visible contraction</td><td>Large-diameter A&beta; afferents</td><td>Segmental gate-control inhibition of dorsal horn transmission; spinal delta-opioid receptor involvement</td></tr><tr><td><strong>Acupuncture-like TENS (AL-TENS)</strong></td><td>Low (~2&ndash;4 Hz)</td><td>High &mdash; visible muscle twitching</td><td>Smaller A&delta; afferents / motor efferents</td><td>Extrasegmental, opioid-mediated (mu-receptor) analgesia via activation of descending inhibitory pathways</td></tr><tr><td><strong>Intense TENS</strong></td><td>High</td><td>Very high &mdash; at or near the limit of tolerability</td><td>Small-diameter A&delta; (and some C) fibres</td><td>Counter-irritation / hyperstimulation analgesia; typically used briefly for short, painful procedures (e.g. wound dressing changes, injections) rather than continuously, as tolerance to the high intensity limits prolonged application</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">TENS Contraindications</div><table style=\"margin:0\"><tr><th>Contraindication / precaution</th><th>Reason</th></tr><tr><td>Cardiac implantable devices</td><td>Pacemakers and implantable cardioverter-defibrillators &mdash; electrical interference can disrupt device sensing/pacing.</td></tr><tr><td>Over the carotid sinus</td><td>Risk of provoking a vasovagal/hypotensive response.</td></tr><tr><td>Over the anterior neck / larynx</td><td>Risk of laryngospasm or interference with airway reflexes.</td></tr><tr><td>Pregnancy</td><td>Avoid placement over the abdomen or lower back, particularly in early pregnancy, due to theoretical uterine stimulation risk (direct evidence of harm is limited).</td></tr><tr><td>Active malignancy at the treatment site</td><td>Theoretical concern regarding electrical stimulation of tumour tissue, though evidence is limited.</td></tr><tr><td>Broken/irritated skin, adhesive allergy</td><td>Local skin precautions.</td></tr><tr><td>Driving, operating machinery, or sleep</td><td>Devices should never be applied then, given the reliance on patient feedback for safe intensity titration.</td></tr><tr><td>Dysaesthesia / diminished sensation</td><td>TENS should not be applied to skin with diminished sensation &mdash; nerve damage is likely to reduce effectiveness and the patient may be unaware that high-intensity currents are causing skin irritation. Caution with mechanical allodynia, as TENS may exacerbate the pain.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Effectiveness</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Clinical experience suggests that TENS may relieve any type of chronic pain, yet systematic reviews are inconclusive for chronic pain, low back pain, cancer-related pain, rheumatoid arthritis of the hand, post-stroke shoulder pain, whiplash and mechanical neck disorders, and chronic recurrent headache. Meta-analyses for osteoarthritic knee pain and for chronic musculoskeletal pain have been more positive, suggesting that TENS is superior to sham TENS for pain and stiffness. Non-randomised controlled clinical trials have found benefit for many types of chronic pain.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">NICE guidance does <strong>not</strong> recommend routinely offering TENS for chronic low back pain.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_nav17_channelopathy_001', 'SBA', '{"dateAdded":"2026-10-12","rotationIndex":144,"question":"A 9-year-old child has never experienced pain, despite repeated fractures and burns. Touch, vibration and temperature discrimination are normal, sweating is normal and the child has no sense of smell. Which genetic abnormality is most likely?","choices":["Mutation of Nav1.7","Mutation of Nav1.8","Mutation of NTRK1 (TrkA receptor)","Mutation of CACNA1A (Cav2.1 channel)","Mutation of TRPV1"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Loss-of-function mutations in SCN9A abolish Nav1.7 current in nociceptors and sympathetic neurones, producing congenital insensitivity to pain; the associated anosmia reflects the role of Nav1.7 in olfactory sensory neurones.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> Nav1.7 (SCN9A) is a tetrodotoxin-sensitive channel that amplifies small sub-threshold depolarisations at the nociceptor terminal. Loss-of-function mutations abolish pain with normal touch and sweating and absent olfaction, as in this child.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Nav1.8 (SCN10A) carries most of the action potential upstroke current in nociceptors, but variants cause altered pain thresholds and small-fibre neuropathy rather than complete painlessness with anosmia.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> NTRK1 mutations cause hereditary sensory and autonomic neuropathy type IV (congenital insensitivity to pain with anhidrosis), where nociceptors fail to develop. Anhidrosis and recurrent fever would be expected; sweating is normal here and smell is intact.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> CACNA1A mutations (Cav2.1, P/Q-type calcium channel) cause familial hemiplegic migraine type 1 and episodic ataxia type 2.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> TRPV1 is a heat- and capsaicin-sensitive channel that contributes to thermal and inflammatory pain; no TRPV1 mutation causes global insensitivity to pain with anosmia.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Voltage-Gated Sodium Channels in Nociception</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Voltage-gated sodium channels generate and propagate the action potential. Several subtypes are enriched in nociceptors and are either implicated in human pain disorders or are drug targets, so they underpin both pain genetics and the pharmacology of local anaesthetics and anticonvulsants.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Nociceptor Sodium Channel Subtypes</div><table style=\"margin:0\"><tr><th>Channel (gene)</th><th>Tetrodotoxin</th><th>Role in nociceptors</th></tr><tr><td>Nav1.7 (SCN9A)</td><td>Sensitive (TTX-S)</td><td>Threshold channel in peripheral nociceptor terminals and sympathetic neurones; amplifies small generator potentials so that the action potential can be triggered</td></tr><tr><td>Nav1.8 (SCN10A)</td><td>Resistant (TTX-R)</td><td>Carries most of the inward current during the action potential upstroke in nociceptors; permits repetitive firing, including in cold and inflammation</td></tr><tr><td>Nav1.9 (SCN11A)</td><td>Resistant (TTX-R)</td><td>Persistent, low-threshold current that sets the resting membrane potential and amplifies sub-threshold input</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Channelopathies</div><table style=\"margin:0\"><tr><th>Variant</th><th>Phenotype</th></tr><tr><td>SCN9A loss of function</td><td>Congenital insensitivity to pain (with anosmia); normal touch, sweating and cognition</td></tr><tr><td>SCN9A gain of function</td><td>Inherited erythromelalgia; paroxysmal extreme pain disorder (altered fast inactivation); small-fibre neuropathy</td></tr><tr><td>SCN10A / SCN11A variants</td><td>Small-fibre neuropathy and altered pain thresholds; SCN11A variants may produce painful or painless phenotypes</td></tr><tr><td>NTRK1 (not a sodium channel)</td><td>Hereditary sensory and autonomic neuropathy type IV: insensitivity to pain with anhidrosis due to loss of nociceptors</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Drugs Acting on Sodium Channels</div><table style=\"margin:0\"><tr><th>Drug class</th><th>Notes</th></tr><tr><td>Local anaesthetics (lidocaine, bupivacaine)</td><td>Non-selective, use-dependent block of all sodium channel subtypes</td></tr><tr><td>Anticonvulsants and antiarrhythmics (carbamazepine, lamotrigine, lacosamide, mexiletine)</td><td>Use-dependent block; benefit in neuropathic pain, trigeminal neuralgia (carbamazepine)</td></tr><tr><td>Selective Nav1.8 inhibition</td><td>Suzetrigine (VX-548) is a selective Nav1.8 inhibitor, approved in the USA for moderate-to-severe acute pain; selectivity avoids the cardiac and central effects of non-selective blockers</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Early Nav1.7-selective inhibitors have so far not translated into reliable analgesia in humans, despite the compelling genetics.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_opioid_receptor_signalling_001', 'MTF', '{"dateAdded":"2026-10-12","rotationIndex":145,"stem":"Regarding opioid receptors:","choices":["Opioid receptors are G protein-coupled receptors linked to Gi/Go","Receptor activation increases adenylyl cyclase activity and intracellular cAMP","Presynaptic opioid receptor activation inhibits voltage-gated calcium channels","Postsynaptic opioid receptor activation opens G protein-coupled inwardly rectifying potassium (GIRK) channels","μ receptor activation is mainly responsible for dysphoria and diuresis"],"correct":[true,false,true,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">All classical opioid receptors (&mu;, &delta;, &kappa;) are inhibitory G protein-coupled receptors. Their combined presynaptic and postsynaptic actions reduce both the release of transmitters from nociceptive afferents and the excitability of the second-order neurone.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; Opioid receptors couple to pertussis toxin-sensitive Gi/Go proteins.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. FALSE</strong> &mdash; The G&alpha;i/o subunit <em>inhibits</em> adenylyl cyclase, so intracellular cAMP and protein kinase A activity fall.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; The G&beta;&gamma; subunit inhibits N-type (Cav2.2) calcium channels on the presynaptic terminals of C and A&delta; fibres, reducing release of glutamate, substance P and CGRP in the dorsal horn.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; Postsynaptically, G&beta;&gamma; opens GIRK channels. K<sup>+</sup> efflux hyperpolarises the neurone, making it less likely to fire.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; Dysphoria, sedation and diuresis are &kappa; receptor effects. &mu; receptor activation causes supraspinal and spinal analgesia, euphoria, respiratory depression, miosis, constipation and physical dependence.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioid Receptor Physiology</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Opioid receptors are Gi/Go-coupled receptors found in the dorsal horn, periaqueductal grey, rostral ventromedial medulla, limbic system, gut, and on peripheral sensory nerve terminals (where expression increases in inflammation). Their cellular effects are uniformly inhibitory.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Signalling</div><div style=\"text-align:center\"><img src=\"images/opioid-receptor-signalling.svg\" alt=\"Flow diagram of opioid receptor signalling: agonist binds a Gi/Go receptor; G-alpha inhibits adenylyl cyclase lowering cAMP; G beta-gamma inhibits presynaptic N-type calcium channels reducing neurotransmitter release and opens postsynaptic GIRK potassium channels causing hyperpolarisation; prolonged exposure leads to phosphorylation, beta-arrestin binding and desensitisation\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Receptor Subtypes</div><table style=\"margin:0\"><tr><th>Receptor</th><th>Main endogenous ligand</th><th>Effects of activation</th></tr><tr><td>&mu; (MOP)</td><td>&beta;-endorphin, endomorphins</td><td>Supraspinal and spinal analgesia, euphoria, respiratory depression, miosis, constipation, bradycardia, physical dependence</td></tr><tr><td>&delta; (DOP)</td><td>Enkephalins</td><td>Spinal and supraspinal analgesia; antidepressant-like effects; lowered seizure threshold</td></tr><tr><td>&kappa; (KOP)</td><td>Dynorphins</td><td>Spinal analgesia, sedation, dysphoria, diuresis, miosis</td></tr><tr><td>Nociceptin (NOP)</td><td>Nociceptin/orphanin FQ</td><td>Not blocked by naloxone; pro-nociceptive supraspinally and anti-nociceptive spinally</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cellular Effects</div><table style=\"margin:0\"><tr><th>Site</th><th>Effect</th><th>Result</th></tr><tr><td>Presynaptic terminal</td><td>Inhibition of N-type Ca<sup>2+</sup> channels</td><td>Reduced release of glutamate, substance P and CGRP</td></tr><tr><td>Postsynaptic neurone</td><td>Opening of GIRK K<sup>+</sup> channels</td><td>Hyperpolarisation and reduced firing</td></tr><tr><td>Intracellular</td><td>Inhibition of adenylyl cyclase; reduced cAMP</td><td>Reduced excitability</td></tr><tr><td>Brainstem (disinhibition)</td><td>Inhibition of GABAergic interneurones in the periaqueductal grey and rostral ventromedial medulla</td><td>Activation of descending inhibitory pathways to the dorsal horn</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Desensitisation follows receptor phosphorylation by G protein-coupled receptor kinases and &beta;-arrestin binding, with internalisation of the receptor. This is one proposed contributor to opioid tolerance.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_sympathetic_neurotransmitters_001', 'SBA', '{"dateAdded":"2026-10-12","rotationIndex":146,"question":"Which of the following statements about peripheral sympathetic neurotransmission is correct?","choices":["Preganglionic sympathetic fibres release noradrenaline onto postganglionic neurones","Postganglionic sympathetic fibres supplying sweat glands release acetylcholine","The adrenal medulla is innervated by postganglionic sympathetic fibres","Transmission at autonomic ganglia is mediated predominantly by muscarinic receptors","Sympathetic preganglionic outflow arises from every spinal segment between C1 and S5"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Sympathetic transmission uses a two-neurone chain. Acetylcholine is the transmitter at every autonomic ganglion and at the adrenal medulla; noradrenaline is the usual postganglionic transmitter, with sweat glands as the classical exception.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Preganglionic sympathetic fibres release acetylcholine, acting on nicotinic receptors on the postganglionic cell body.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> Sympathetic fibres to eccrine sweat glands are cholinergic: they release acetylcholine onto muscarinic receptors. (Sympathetic vasodilator fibres to skeletal muscle in some species are also cholinergic.) Most other postganglionic fibres release noradrenaline.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> The adrenal medulla is innervated directly by <em>preganglionic</em> fibres (via the greater splanchnic nerve). The chromaffin cells are modified postganglionic neurones and release mainly adrenaline (about 80%) and noradrenaline (about 20%).</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Ganglionic transmission is predominantly nicotinic (Nn receptors, blocked by hexamethonium). Muscarinic receptors modulate ganglionic transmission as a slow, minor component.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Sympathetic outflow is thoracolumbar, from T1 to L2 (sometimes L3). Cranial and sacral outflows are parasympathetic.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Autonomic Nervous System</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Combined Reference Table</div><table style=\"margin:0\"><tr><th>Feature</th><th>Sympathetic</th><th>Parasympathetic</th></tr><tr><td>Spinal outflow</td><td>Thoracolumbar (T1&ndash;L2)</td><td>Craniosacral (CN III, VII, IX, X; S2&ndash;S4)</td></tr><tr><td>Preganglionic neuron length</td><td>Short</td><td>Long</td></tr><tr><td>Preganglionic neurotransmitter</td><td>Acetylcholine</td><td>Acetylcholine</td></tr><tr><td>Preganglionic receptor (on ganglion)</td><td>Nicotinic (N<sub>n</sub>)</td><td>Nicotinic (N<sub>n</sub>)</td></tr><tr><td>Ganglion location</td><td>Close to spinal cord (paravertebral chain / prevertebral ganglia, e.g. coeliac, mesenteric)</td><td>Close to, or within, the target organ wall (e.g. cardiac plexus, myenteric plexus, ciliary ganglion)</td></tr><tr><td>Postganglionic neuron length</td><td>Long</td><td>Short</td></tr><tr><td>Postganglionic neurotransmitter (most targets)</td><td>Noradrenaline</td><td>Acetylcholine</td></tr><tr><td>Postganglionic receptor (most targets)</td><td>Alpha (&alpha;1, &alpha;2) / Beta (&beta;1, &beta;2, &beta;3) adrenoreceptors</td><td>Muscarinic (M1&ndash;M5)</td></tr><tr><td>Exception &mdash; sweat glands (eccrine)</td><td>Sympathetic, but the postganglionic transmitter is <strong>acetylcholine</strong> &rarr; muscarinic receptors</td><td>&mdash;</td></tr><tr><td>Exception &mdash; adrenal medulla</td><td>Preganglionic fibre synapses <strong>directly</strong> on chromaffin cells (no postganglionic neuron); releases ACh &rarr; nicotinic receptors; chromaffin cells then secrete adrenaline (~80%) and noradrenaline (~20%) into the bloodstream as hormones</td><td>&mdash;</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Neurotransmitters &amp; receptors of the pre- and postganglionic neurons</div><div style=\"text-align:center\"><img src=\"images/autonomic-preganglionic-postganglionic-neurons.png\" alt=\"Diagram comparing the parasympathetic and sympathetic nervous systems — preganglionic and postganglionic fibre lengths with acetylcholine, noradrenaline, nicotinic, muscarinic and adrenergic receptors marked\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_local_anaesthetic_action_001', 'MTF', '{"dateAdded":"2026-10-12","rotationIndex":147,"stem":"Regarding the mechanism of action of local anaesthetics:","choices":["The ionised form binds to the voltage-gated sodium channel from the intracellular side","Block is use-dependent, with greater affinity for open and inactivated channels than resting channels","Agents with a higher pKa have a faster onset of action","Efficacy is reduced in infected, acidic tissue","They act by hyperpolarising the resting membrane potential"],"correct":[true,true,false,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Local anaesthetics are weak bases. The un-ionised, lipid-soluble base crosses the nerve membrane; once inside, the ionised form blocks the inner pore of the voltage-gated sodium channel, preventing the rise in sodium conductance needed for propagation of the action potential.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; The base diffuses into the axon, re-equilibrates, and the ionised (cationic) form binds a receptor site within the channel pore on the cytoplasmic side.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Local anaesthetics bind with higher affinity to open and inactivated channel states (state-dependent, or use-dependent, block). Rapidly firing fibres are therefore blocked preferentially.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Onset is faster with a <em>lower</em> pKa. A pKa closer to tissue pH (7.4) means a larger fraction exists as un-ionised base, which can cross the membrane. Lidocaine (pKa 7.9) acts faster than bupivacaine (pKa 8.1).</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; In acidic tissue the equilibrium shifts towards the ionised form, so less base is available to cross the membrane, and block is slower and weaker.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; Local anaesthetics do not alter the resting membrane potential. They raise the threshold for excitation and slow the rate of rise of the action potential until propagation fails.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Local Anaesthetics</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Local anaesthetics (LAs) are weak bases that reversibly block voltage-gated sodium channels from the intracellular side of the neuronal membrane, preventing sodium influx, action potential propagation, and nerve conduction. To reach this intracellular binding site, the uncharged (lipid-soluble) form must first cross the lipid membrane; a proportion then re-ionises intracellularly to the charged form, which is the active species at the sodium channel.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Ionisation and Site of Action</div><div style=\"text-align:center\"><img src=\"images/local-anaesthetic-ionisation.svg\" alt=\"Diagram of local anaesthetic action: ionised and un-ionised forms in equilibrium outside the axon, the lipid-soluble base crossing the membrane, re-equilibration inside, and the ionised form blocking the inner pore of the sodium channel\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification</div><table style=\"margin:0\"><tr><th>Class</th><th>Examples</th><th>Notes</th></tr><tr><td>Esters</td><td>Cocaine, procaine, tetracaine, chloroprocaine</td><td>Metabolised by plasma cholinesterase; higher allergy potential (PABA metabolite)</td></tr><tr><td>Amides</td><td>Lidocaine, bupivacaine, levobupivacaine, ropivacaine, prilocaine</td><td>Metabolised hepatically; recognised by two \"i\"s in the name before \"-caine\"</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Factors Affecting Clinical Effect</div><table style=\"margin:0\"><tr><th>Factor</th><th>Effect</th></tr><tr><td>pKa (onset)</td><td>pKa is the pH at which 50% of the drug is ionised and 50% unionised. The unionised (lipophilic) form crosses the membrane, so a lower pKa (closer to pH 7.4) gives more unionised drug and a faster onset (e.g. lidocaine, pKa ~7.9, is faster than bupivacaine, ~8.1). In infected / acidic tissue more drug stays ionised, reducing membrane penetration and LA efficacy.</td></tr><tr><td>Lipid solubility (potency)</td><td>Higher lipid solubility &rarr; easier passage through the lipid-rich neuronal membrane &rarr; greater potency.</td></tr><tr><td>Protein binding (duration)</td><td>LAs bind mainly to alpha-1 acid glycoprotein (and albumin). Higher protein binding means the drug stays bound at the sodium channel longer &rarr; longer duration (bupivacaine ~95% bound lasts far longer than lidocaine ~65%).</td></tr><tr><td>Dose / concentration / volume</td><td>A higher total dose increases the concentration gradient driving diffusion into the nerve, affecting onset speed and block density / duration.</td></tr><tr><td>Vasoactivity</td><td>Most LAs (except cocaine, which is vasoconstrictive) cause vasodilation, increasing systemic absorption and shortening local duration. Added adrenaline counteracts this &mdash; prolonging the block and lowering peak plasma concentration by reducing vascular uptake.</td></tr><tr><td>Site of injection</td><td>Highly vascular sites (e.g. intercostal block) &rarr; faster systemic absorption, shorter duration, higher plasma levels. Poorly vascular sites (e.g. subcutaneous) &rarr; slower absorption, longer local duration.</td></tr><tr><td>Fibre type / diameter</td><td>Smaller fibres are generally blocked first (B sympathetic fibres, then C and A&delta; pain and temperature fibres, then A&beta; touch, with A&alpha; motor fibres last), so sympathetic and sensory block precede motor block. See the Peripheral Nerve Fibre Types knowledge box.</td></tr><tr><td>State-dependent (use-dependent) block</td><td>LAs bind with higher affinity to open and inactivated sodium channels than to resting channels, so rapidly firing fibres are blocked preferentially. The resting membrane potential is unchanged: the block raises the firing threshold and slows depolarisation until propagation fails.</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">pKa and Onset</div><table style=\"margin:0\"><tr><th>Agent</th><th>pKa</th><th>Approx. un-ionised fraction at pH 7.4</th><th>Onset</th></tr><tr><td>Mepivacaine</td><td>7.7</td><td>33%</td><td>Fast</td></tr><tr><td>Lidocaine</td><td>7.9</td><td>24%</td><td>Fast</td></tr><tr><td>Bupivacaine / levobupivacaine</td><td>8.1</td><td>17%</td><td>Intermediate</td></tr><tr><td>Ropivacaine</td><td>8.1</td><td>17%</td><td>Intermediate</td></tr><tr><td>Chloroprocaine</td><td>8.7</td><td>5%</td><td>Fast, because of the high concentration used</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Fractions calculated from the Henderson&ndash;Hasselbalch equation; published pKa values vary slightly between sources. Adding sodium bicarbonate raises pH, increases the un-ionised fraction and shortens onset.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_csf_physiology_001', 'SBA', '{"dateAdded":"2026-10-12","rotationIndex":148,"question":"Which of the following correctly describes the composition of normal adult cerebrospinal fluid compared with plasma?","choices":["The protein concentration is similar to that of plasma","The chloride concentration is lower than that of plasma","The potassium concentration is higher than that of plasma","The glucose concentration is approximately 60–65% of the plasma value","The pH is higher than that of arterial blood"],"correct":3,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Cerebrospinal fluid is an actively secreted, tightly regulated ultrafiltrate-like fluid whose composition differs from plasma, so it is not a simple filtrate. CSF glucose is normally about 60&ndash;65% of the simultaneous plasma value.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> CSF protein is very low (about 0.15&ndash;0.45 g/L, roughly 0.5% of plasma), because the blood&ndash;CSF barrier restricts the passage of large molecules.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> CSF chloride (about 120 mmol/L) is <em>higher</em> than plasma (about 100 mmol/L), balancing the lower protein anion content.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> CSF potassium (about 3 mmol/L) is <em>lower</em> than plasma and is tightly regulated, as it influences neuronal excitability.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Correct.</strong> Glucose enters CSF by facilitated transport and is maintained at about 60&ndash;65% of the plasma concentration; a markedly low CSF glucose suggests bacterial meningitis.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> CSF pH (about 7.33) is slightly <em>lower</em> than arterial blood (7.40), with a slightly higher PCO<sub>2</sub>.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Cerebrospinal Fluid Physiology</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">CSF is produced mainly by the choroid plexuses of the lateral, third and fourth ventricles, circulates through the ventricular system into the subarachnoid space, and is absorbed back into the venous blood. Its volume, pressure, density and composition matter for intrathecal drug spread, lumbar puncture and post-dural puncture headache.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Key Values</div><table style=\"margin:0\"><tr><th>Parameter</th><th>Typical adult value</th></tr><tr><td>Total volume</td><td>About 150 mL (ventricles about 25 mL; spinal subarachnoid space about 25&ndash;35 mL)</td></tr><tr><td>Production rate</td><td>About 0.35 mL/min (about 500 mL/day); the whole volume is replaced 3&ndash;4 times daily</td></tr><tr><td>Opening pressure (lateral position)</td><td>About 7&ndash;18 cmH<sub>2</sub>O</td></tr><tr><td>Density at 37&deg;C</td><td>About 1.0003&ndash;1.0008 g/mL (reference for hyperbaric and hypobaric intrathecal solutions)</td></tr><tr><td>Cells</td><td>0&ndash;5 lymphocytes per &micro;L</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Composition Compared with Plasma</div><table style=\"margin:0\"><tr><th>Constituent</th><th>CSF</th><th>Plasma</th><th>Comment</th></tr><tr><td>Protein</td><td>0.15&ndash;0.45 g/L</td><td>60&ndash;80 g/L</td><td>Raised in meningitis, Guillain&ndash;Barr&eacute; syndrome, spinal block</td></tr><tr><td>Glucose</td><td>2.8&ndash;4.4 mmol/L</td><td>3.5&ndash;5.5 mmol/L</td><td>About 60&ndash;65% of plasma; low in bacterial meningitis</td></tr><tr><td>Sodium</td><td>&asymp; 140 mmol/L</td><td>&asymp; 140 mmol/L</td><td>Similar</td></tr><tr><td>Chloride</td><td>&asymp; 120 mmol/L</td><td>&asymp; 100 mmol/L</td><td>Higher in CSF</td></tr><tr><td>Potassium</td><td>&asymp; 3 mmol/L</td><td>&asymp; 4.5 mmol/L</td><td>Lower and tightly regulated</td></tr><tr><td>pH</td><td>&asymp; 7.33</td><td>7.35&ndash;7.45</td><td>Slightly acidic relative to blood</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Circulation and Absorption</div><table style=\"margin:0\"><tr><th>Step</th><th>Detail</th></tr><tr><td>Formation</td><td>Active secretion by choroid plexus epithelium (also a small contribution from brain interstitial fluid)</td></tr><tr><td>Flow</td><td>Lateral ventricles &rarr; foramina of Monro &rarr; third ventricle &rarr; aqueduct of Sylvius &rarr; fourth ventricle &rarr; foramina of Luschka and Magendie &rarr; subarachnoid space</td></tr><tr><td>Absorption</td><td>Bulk flow through arachnoid granulations into the superior sagittal sinus; absorption depends on the CSF&ndash;venous pressure gradient and is not dependent on production rate</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Clinical relevance: loss of CSF through a dural puncture reduces CSF pressure and volume, producing a postural headache; hydrophilic intrathecal opioids such as morphine spread rostrally with CSF bulk flow, which underlies the risk of delayed respiratory depression.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_visceral_referred_pain_001', 'MTF', '{"dateAdded":"2026-10-12","rotationIndex":149,"stem":"Regarding visceral and referred pain:","choices":["Most visceral nociceptive afferents travel with sympathetic nerves to cell bodies in the dorsal root ganglia","Convergence of visceral and somatic afferents onto the same dorsal horn neurones is thought to underlie referred pain","Visceral pain is typically sharp and precisely localised","Hollow viscera are highly sensitive to cutting and burning","Irritation of the central diaphragm commonly causes pain referred to the shoulder tip"],"correct":[true,true,false,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Visceral pain is diffuse and poorly localised, and is often felt at a distant superficial site. Visceral afferents are sparse compared with somatic afferents, and converge with them in the dorsal horn.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; The great majority of visceral nociceptors travel with sympathetic efferents (for example the splanchnic nerves) to dorsal root ganglia at T1&ndash;L2. Some travel with the vagus (upper gut) and the pelvic splanchnic nerves (pelvic viscera, S2&ndash;S4).</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; This is the convergence&ndash;projection theory: visceral and somatic afferents synapse on the same second-order neurones, so the brain interprets the visceral input as coming from the more familiar somatic dermatome.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Visceral pain is dull, deep, poorly localised, often midline, and accompanied by autonomic features (nausea, sweating, pallor). Sharp, well-localised pain occurs once the parietal peritoneum or pleura is involved.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Viscera are largely insensitive to cutting and burning. Adequate stimuli are distension, traction, ischaemia, spasm and inflammation, and sensitivity is greatly enhanced by inflammation.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; The central diaphragm is supplied by the phrenic nerve (C3&ndash;C5), so peritoneal or pleural irritation of the central diaphragm is referred to the C3&ndash;C5 dermatomes at the shoulder tip.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Dorsal Horn, Visceral and Referred Pain</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Pain primary afferents enter the dorsal horn of the spinal cord, synapsing ipsilaterally with 2nd order neurons. In cross section, the spinal cord resembles an oval of white matter (myelinated axons), surrounding an H-shaped centre of grey matter (cell bodies). The grey matter is arranged into ten histological layers, or laminae, based on cytological architecture, known as Rexed''s laminae. The dorsal horn is made up of laminae I&ndash;V.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Rexed Laminae</div><div style=\"text-align:center\"><img src=\"images/rexed-laminae.png\" alt=\"Rexed laminae — spinal cord grey matter cross-section with laminae I–X labelled alongside a table of regions, nuclei and corresponding laminae\" style=\"max-width:100%;border-radius:10px;margin-top:0;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Primary Afferent Termination</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A&delta; primary afferents terminate on laminae I and V, and C fibres terminate on lamina II, the substantia gelatinosa. A&delta; primary afferents synapse directly with secondary afferents that will eventually carry the pain signal to the thalamus. C fibres do not synapse directly with secondary afferents, but connect instead with interneurons that carry the signal on to secondary afferents in laminae I or V. These interneurons are important in modulation of the pain signal.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Visceral input differs in that fewer primary afferents activate a larger number of second order neurons, resulting in poorer localisation of pain. Visceral afferents also converge with somatic inputs, which may account for the phenomenon of referred pain.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Convergence&ndash;Projection</div><div style=\"text-align:center\"><img src=\"images/referred-pain-convergence.svg\" alt=\"Diagram of convergence-projection theory: visceral afferent from the heart and somatic afferent from the left arm converge on the same second-order dorsal horn neurone and project via the spinothalamic tract, so pain is perceived in the arm\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Visceral Versus Somatic Pain</div><table style=\"margin:0\"><tr><th>Feature</th><th>Visceral pain</th><th>Somatic pain</th></tr><tr><td>Quality</td><td>Dull, aching, cramping, colicky</td><td>Sharp, well defined</td></tr><tr><td>Localisation</td><td>Poor, often midline</td><td>Good, at site of injury</td></tr><tr><td>Adequate stimulus</td><td>Distension, traction, ischaemia, spasm, inflammation</td><td>Cutting, burning, pressure</td></tr><tr><td>Accompanying features</td><td>Autonomic: nausea, sweating, pallor</td><td>Few</td></tr><tr><td>Referral</td><td>Common, to somatic structures of the same segment</td><td>Uncommon</td></tr><tr><td>Afferent route</td><td>Sympathetic (mainly), vagal, pelvic parasympathetic</td><td>Spinal nerves</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Common Referral Patterns</div><table style=\"margin:0\"><tr><th>Organ</th><th>Spinal segments</th><th>Referred site</th></tr><tr><td>Heart</td><td>T1&ndash;T4</td><td>Central chest, left arm, jaw</td></tr><tr><td>Diaphragm (central)</td><td>C3&ndash;C5</td><td>Shoulder tip</td></tr><tr><td>Gallbladder</td><td>T7&ndash;T9</td><td>Right subscapular region, right shoulder</td></tr><tr><td>Pancreas</td><td>T6&ndash;T10</td><td>Epigastrium radiating to the back</td></tr><tr><td>Appendix</td><td>T10</td><td>Periumbilical, later localising to the right iliac fossa when the parietal peritoneum is involved</td></tr><tr><td>Kidney and ureter</td><td>T10&ndash;L1</td><td>Loin radiating to the groin and genitalia</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Approximate segmental levels; individual variation is common. Hyperalgesia and muscle tenderness in the referred area are well described.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_spinothalamic_brown_sequard_001', 'SBA', '{"dateAdded":"2026-10-12","rotationIndex":150,"question":"A 52-year-old man sustains a stab wound causing a right-sided hemisection of the spinal cord at T10 (Brown-Séquard syndrome). Which sensory deficit would be expected below the level of the lesion?","choices":["Loss of pain and temperature on the right, and loss of vibration and proprioception on the left","Loss of pain and temperature on the left, and loss of vibration and proprioception on the right","Loss of all sensory modalities on the right","Loss of pain and temperature bilaterally, with preserved vibration and proprioception","Loss of all sensory modalities on the left"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The anterolateral (spinothalamic) system decussates within one or two segments of entry, in the anterior white commissure, then ascends contralaterally. The dorsal columns ascend ipsilaterally and cross in the medulla. A hemisection therefore produces a dissociated sensory loss.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> This reverses the pattern. Pain and temperature fibres have already crossed, so they are lost on the side <em>opposite</em> the lesion, and dorsal column modalities are lost on the <em>same</em> side.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> Spinothalamic fibres cross to the left side near their level of entry and are interrupted by the right hemisection, so pain and temperature are lost on the left (usually beginning one to two segments below the lesion). The right dorsal column has not yet crossed, so vibration and proprioception are lost on the right. There is also ipsilateral (right) upper motor neurone weakness below the lesion.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Loss of all modalities on one side would require the pathways to run together ipsilaterally, which they do not.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Bilateral loss of pain and temperature with preserved dorsal columns is the pattern of a central cord lesion such as syringomyelia (cape-like distribution) affecting the crossing fibres.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Loss of all modalities on the left would not occur, since vibration and proprioception are ipsilateral to the lesion.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Ascending Pain Pathways</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Nociceptive information ascends in the anterolateral quadrant of the spinal cord in several parallel tracts, which together carry the sensory-discriminative, affective-motivational and autonomic dimensions of pain. The tracts cross in the spinal cord, in contrast to the dorsal columns, which cross in the medulla.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Ascending Tracts</div><table style=\"margin:0\"><tr><th>Tract</th><th>Origin (lamina)</th><th>Termination</th><th>Function</th></tr><tr><td>Lateral spinothalamic (neospinothalamic)</td><td>I, V</td><td>Ventral posterolateral thalamus &rarr; S1/S2</td><td>Sensory-discriminative: location, intensity, quality of pain; temperature</td></tr><tr><td>Anterior spinothalamic</td><td>III&ndash;VI</td><td>Thalamus</td><td>Crude touch and pressure</td></tr><tr><td>Spinoreticular</td><td>VII, VIII</td><td>Brainstem reticular formation, then medial thalamus</td><td>Arousal and autonomic response</td></tr><tr><td>Spinomesencephalic</td><td>I, V</td><td>Periaqueductal grey, superior colliculus</td><td>Orientation to pain; activation of descending modulation</td></tr><tr><td>Spinoparabrachial / spinohypothalamic</td><td>I</td><td>Parabrachial nucleus, amygdala, hypothalamus</td><td>Affective-motivational and neuroendocrine aspects of pain</td></tr><tr><td>Dorsal column&ndash;medial lemniscus</td><td>Primary afferent A&beta; collaterals</td><td>Gracile and cuneate nuclei (medulla), then cross to thalamus</td><td>Vibration, proprioception, fine touch</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Correlates</div><table style=\"margin:0\"><tr><th>Lesion or procedure</th><th>Effect</th></tr><tr><td>Brown-S&eacute;quard (hemisection)</td><td>Ipsilateral loss of dorsal column modalities and UMN weakness below the lesion; contralateral loss of pain and temperature</td></tr><tr><td>Syringomyelia (central cord)</td><td>Cape-like, bilateral loss of pain and temperature with preserved dorsal column function, from interruption of crossing spinothalamic fibres</td></tr><tr><td>Anterior spinal artery occlusion</td><td>Bilateral loss of pain and temperature and motor function with preserved dorsal column function</td></tr><tr><td>Percutaneous cordotomy (C1&ndash;C2)</td><td>Interrupts the anterolateral tract to give contralateral analgesia, used for unilateral cancer pain; risks include ipsilateral Horner syndrome and, if bilateral, impaired respiratory drive (Ondine&rsquo;s curse)</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_endogenous_opioid_peptides_001', 'SBA', '{"dateAdded":"2026-10-12","rotationIndex":151,"question":"Which of the following correctly pairs an endogenous opioid peptide with its precursor?","choices":["β-endorphin – proenkephalin","Enkephalins – prodynorphin","Dynorphins – prodynorphin","Endomorphins – pro-opiomelanocortin","Nociceptin/orphanin FQ – pro-opiomelanocortin"],"correct":2,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Each family of endogenous opioid peptides is cleaved from its own large precursor: pro-opiomelanocortin (POMC), proenkephalin and prodynorphin, with nociceptin arising from pronociceptin.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> &beta;-endorphin is cleaved from pro-opiomelanocortin (POMC), alongside ACTH and &alpha;-MSH; proenkephalin is the precursor of the enkephalins.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> The enkephalins (Met- and Leu-enkephalin) are derived from proenkephalin, not prodynorphin.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Correct.</strong> Prodynorphin yields the dynorphins (A and B) and &alpha;-neo-endorphin, which act mainly at the &kappa; receptor.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Endomorphin-1 and -2 are the exception: they are highly selective &mu; agonists but no classical precursor gene has been identified for them, and they are not derived from POMC.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Nociceptin/orphanin FQ is derived from pronociceptin, not POMC, and acts at the NOP receptor rather than the classical opioid receptors.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Inhibitory Neurotransmitters and Endogenous Opioid Peptides</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Pain transmission in the dorsal horn is restrained by inhibitory transmitters released from local interneurones and descending pathways. The endogenous opioid peptides are among them; each family is cleaved from its own precursor, and they are released in response to stress and noxious stimulation.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Inhibitory Neurotransmitters in the Pain Pathway</div><table style=\"margin:0\"><tr><th colspan=\"3\" style=\"text-align:center\">Inhibitory neurotransmitters in the pain pathway</th></tr><tr><td><strong>Neurotransmitter</strong></td><td><strong>Full name(s)</strong></td><td><strong>Receptor in dorsal horn</strong></td></tr><tr><td><strong>GABA</strong></td><td>Gamma-aminobutyric acid</td><td>GABA<sub>A</sub>, GABA<sub>B</sub></td></tr><tr><td><strong>Gly</strong></td><td>Glycine</td><td>Glycine (strychnine-sensitive)</td></tr><tr><td><strong>Endorphins</strong></td><td>&beta;-endorphins</td><td>Opioid (&mu;&gt;&delta;,&kappa;)</td></tr><tr><td><strong>Enkephalins</strong></td><td>Met- and Leu-enkephalin, Enk-8</td><td>Opioid (&delta;&gt;&mu;,&kappa;)</td></tr><tr><td><strong>Dynorphins</strong></td><td>Dynorphin-A, Dynorphin-B</td><td>Opioid (&kappa;&gt;&mu;,&delta;)</td></tr><tr><td><strong>Endocannabinoids</strong></td><td>Anandamide (AEA), 2-arachidonoylglycerol (2-AG)</td><td>CB<sub>1</sub></td></tr><tr><td><strong>5-HT</strong></td><td>5-hydroxytryptamine (serotonin)</td><td>5-HT receptor subtypes 1&ndash;3</td></tr><tr><td><strong>NA</strong></td><td>Noradrenaline</td><td>&alpha;<sub>2</sub>-adrenergic</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Endogenous Opioid Peptides and Precursors</div><table style=\"margin:0\"><tr><th>Peptide</th><th>Precursor</th><th>Notes</th></tr><tr><td>&beta;-endorphin</td><td>Pro-opiomelanocortin (POMC)</td><td>Released with ACTH from the pituitary, and from hypothalamic arcuate neurones; also released by immune cells in inflamed tissue</td></tr><tr><td>Met- and Leu-enkephalin</td><td>Proenkephalin</td><td>Widespread: dorsal horn interneurones, periaqueductal grey, rostral ventromedial medulla, adrenal medulla</td></tr><tr><td>Dynorphins A and B</td><td>Prodynorphin</td><td>Dorsal horn, hypothalamus; implicated in dysphoria; may be pro-nociceptive in chronic pain states</td></tr><tr><td>Endomorphin-1 and -2</td><td>No classical precursor identified</td><td>Highly selective &mu; agonists found in brainstem and spinal cord</td></tr><tr><td>Nociceptin/orphanin FQ</td><td>Pronociceptin</td><td>Acts at the NOP receptor, not blocked by naloxone; supraspinal anti-opioid and spinal analgesic actions</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Roles in Pain Modulation</div><table style=\"margin:0\"><tr><th>Site or setting</th><th>Role</th></tr><tr><td>Periaqueductal grey and rostral ventromedial medulla</td><td>Opioid peptides inhibit GABAergic interneurones, disinhibiting descending pathways that suppress dorsal horn transmission</td></tr><tr><td>Dorsal horn</td><td>Enkephalinergic interneurones inhibit release from primary afferents and excitability of projection neurones</td></tr><tr><td>Peripheral inflamed tissue</td><td>Immune cells release &beta;-endorphin and enkephalins that act on peripheral opioid receptors on nociceptor terminals</td></tr><tr><td>Stress and exercise</td><td>Release of &beta;-endorphin and enkephalins contributes to stress-induced analgesia; effects are naloxone-reversible</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;

